package com.lendup.reservas.config.security;
import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import java.util.List; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.web.filter.OncePerRequestFilter;
public class FirebaseAuthenticationFilter extends OncePerRequestFilter { private final TokenVerifier verifier; public FirebaseAuthenticationFilter(TokenVerifier v){verifier=v;} protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")){try{VerifiedToken t=verifier.verify(h.substring(7));if(!t.emailVerified()){json(res,403,"EMAIL_NOT_VERIFIED","Verifica tu correo para ingresar a LendUp");return;}var authorities=t.administrator()?List.of(new SimpleGrantedAuthority("ROLE_ADMINISTRADOR")):List.<SimpleGrantedAuthority>of();var auth=new UsernamePasswordAuthenticationToken(t.uid(),null,authorities);auth.setDetails(t);SecurityContextHolder.getContext().setAuthentication(auth);}catch(Exception e){json(res,401,"TOKEN_INVALIDO","Token Firebase no válido");return;}}chain.doFilter(req,res);} private void json(HttpServletResponse r,int s,String e,String m)throws IOException{r.setStatus(s);r.setContentType("application/json");r.getWriter().write("{\"status\":"+s+",\"error\":\""+e+"\",\"message\":\""+m+"\"}");}}
